# `description` says what the SOURCE field is -- what it means is dab/model.yaml's job.
endpoints:
  source:
    provider: northwind_odata
    base_url: https://demodata.grapecity.com/northwind/odata/v1/
    entity: Orders # entity set == URL path segment == recorded payload Orders.json
