# A neutral contract. It names nothing from any business, so a test over it proves the
# machinery works for a contract rather than for ours. docs/conventions.md section 6.
primary_keys: [parent_id]
columns:
  - {source_path: ParentId, target_name: parent_id, type: INTEGER, mode: REQUIRED, description: The key.}
  - {source_path: ParentLabel, target_name: parent_label, type: STRING, mode: NULLABLE, description: A label.}
  - {source_path: ParentCount, target_name: parent_count, type: BIGINT, mode: NULLABLE, description: A count.}
  - {source_path: ParentRatio, target_name: parent_ratio, type: DOUBLE, mode: NULLABLE, description: A ratio.}
  - {source_path: ParentAmount, target_name: parent_amount, type: DECIMAL(18, 4), mode: NULLABLE, description: An amount.}
  - {source_path: ParentFlag, target_name: parent_flag, type: BOOLEAN, mode: NULLABLE, description: A flag.}
  - {source_path: ParentOn, target_name: parent_on, type: DATE, mode: NULLABLE, description: A date.}
  - {source_path: ParentAt, target_name: parent_at, type: TIMESTAMP, mode: NULLABLE, description: An instant.}
  - {source_path: ParentBlob, target_name: parent_blob, type: JSON, mode: NULLABLE, description: A nested value.}
YML
cat > tests/test_contract.py <<'PY'
"""A contract is documentation, schema and transformation in one artefact. ADR 0003."""

from pathlib import Path

import pytest

from adss.contract import ColumnType, ContractError, read_contract

FIXTURES = Path(__file__).parent / "fixtures" / "contracts"


def parent_contract():
    return read_contract(FIXTURES / "parent.yaml")


def test_the_file_stem_is_the_landed_table_name():
    assert parent_contract().table == "parent"


def test_every_declared_column_is_read_in_order():
    contract = parent_contract()
    assert len(contract.columns) == 9
    assert contract.columns[0].source_path == "ParentId"
    assert contract.columns[0].target_name == "parent_id"
    assert contract.columns[0].required is True
    assert contract.columns[1].required is False


def test_the_whole_type_vocabulary_is_exercised_by_the_fixture():
    declared = {column.type.name for column in parent_contract().columns}
    assert declared == set(ColumnType.__members__), (
        "every type in the vocabulary must appear in the neutral fixture, or its emitted "
        "expression is never tested"
    )


